package java.util;
public abstract class AbstractSequentialList<E> extends AbstractList<E> { protected AbstractSequentialList(){} public E get(int i){try{return listIterator(i).next();}catch(NoSuchElementException e){throw new IndexOutOfBoundsException();}} public E set(int i,E e){try{ListIterator<E> it=listIterator(i);E old=it.next();it.set(e);return old;}catch(NoSuchElementException x){throw new IndexOutOfBoundsException();}} public void add(int i,E e){listIterator(i).add(e);} public E remove(int i){try{ListIterator<E> it=listIterator(i);E e=it.next();it.remove();return e;}catch(NoSuchElementException e){throw new IndexOutOfBoundsException();}} public Iterator<E> iterator(){return listIterator();} public abstract ListIterator<E> listIterator(int index); }
